def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    c_opp = opp.count('C')
    d_opp = n - c_opp

    if d_opp == 0:
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp[-1]
    last_mine = me[-1]

    streak_d = 0
    i = n - 1
    while i >= 0 and opp[i] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp[i] == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n
    recent = opp[-8:]
    recent_d = recent.count('D')
    recent_c = len(recent) - recent_d

    mirror_score = 0
    if n >= 3:
        for i in range(1, n):
            if opp[i] == me[i - 1]:
                mirror_score += 1
        mirror_ratio = mirror_score / (n - 1)
    else:
        mirror_ratio = 0.0

    remaining = 100 - n

    if remaining <= 4:
        if streak_d > 0:
            return 'D'
        if coop_rate > 0.7 or mirror_ratio > 0.6:
            return 'D'
        if recent_c >= 3:
            return 'D'
        return 'C'

    if remaining <= 10:
        if streak_d > 0:
            return 'D'
        if recent_d == 0 and coop_rate > 0.75:
            return 'D'
        if coop_rate >= 0.6:
            return 'C'
        return 'D'

    if streak_d >= 3:
        return 'D'

    if streak_d == 2:
        if coop_rate > 0.75 and recent_c >= 4:
            return 'C'
        return 'D'

    if streak_d == 1:
        if recent_d <= 1 and coop_rate > 0.65:
            return 'C'
        if last_mine == 'D':
            return 'C'
        return 'D'

    if coop_rate >= 0.85 and recent_d == 0:
        if n > 25 and rng.random() < 0.03:
            return 'D'
        return 'C'

    if mirror_ratio > 0.7 and n >= 6:
        return me[-1]

    if n >= 6:
        alt_score = 0
        for i in range(1, n):
            if opp[i] != opp[i - 1]:
                alt_score += 1
        if alt_score >= n - 2:
            return 'D' if last == 'C' else 'C'

    if last == 'C':
        if recent_d == 0:
            return 'C'
        if coop_rate > 0.6 and rng.random() < 0.7:
            return 'C'
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    if coop_rate > 0.6 and streak_d == 0:
        return 'C'
    if coop_rate > 0.5 and rng.random() < 0.25:
        return 'C'
    return 'D'
